/* @lc app=leetcode id=2851 lang=kotlin */ class Solution { fun numberOfWays(s: String, t: String, k: Long): Int = s.length.let { n -> (t + '#' + s + s.dropLast(1)).let { c -> IntArray(c.length).let { pi -> (1 until c.length).fold(0) { occ, i -> generateSequence(pi[i - 1]) { if (it > 0 && c[it] != c[i]) pi[it - 1] else null }.last().let { k0 -> (if (c[k0] == c[i]) k0 + 1 else k0).also { pi[i] = it }.let { occ + if (it == n) 1 else 0 } } }.let { occ -> (if (s == t) 1 else 0).let { z -> java.math.BigInteger.valueOf(1_000_000_007).let { P -> java.math.BigInteger.valueOf(n - 1L).modPow(java.math.BigInteger.valueOf(k), P).let { pw -> (if (k % 2 == 0L) java.math.BigInteger.ONE else java.math.BigInteger.ONE.negate()).let { sg -> java.math.BigInteger.valueOf(n.toLong()).modInverse(P).let { inv -> (((pw + sg * (n - 1).toBigInteger()) * inv).mod(P) * z.toBigInteger() + ((pw - sg) * inv).mod(P) * (occ - z).toBigInteger()).mod(P).toInt() } } } } } } } } } }